"""Inference and Insurance Cost Prediction Module.

Validates single or batch patient profiles, loads serialized Scikit-Learn
pipelines, computes estimated insurance charges, and includes academic disclaimers.
"""

from pathlib import Path
from typing import Dict, Any, Union, Optional
import joblib
import pandas as pd
from sklearn.pipeline import Pipeline

from src.config import BEST_MODEL_PATH, ALL_FEATURES, logger
from src.preprocessing import validate_single_record


EDUCATIONAL_DISCLAIMER = (
    "DISCLAIMER: This prediction is generated by an educational academic machine "
    "learning model (College CA2 Project) trained on historical medical cost benchmarks. "
    "It is NOT a formal insurance underwriting quote, financial advice, or medical assessment."
)


def load_best_model(model_path: Optional[Path] = None) -> Pipeline:
    """Load the serialized best regression pipeline.

    Args:
        model_path: Path to joblib file. Defaults to BEST_MODEL_PATH.

    Returns:
        Loaded Scikit-Learn Pipeline.

    Raises:
        FileNotFoundError: If model pipeline has not been trained yet.
    """
    path = Path(model_path or BEST_MODEL_PATH)
    if not path.exists():
        msg = (
            f"Trained model artifact not found at {path.resolve()}.\n"
            "Please train the model first by running:\n"
            "    python main.py train"
        )
        logger.error(msg)
        raise FileNotFoundError(msg)

    pipeline = joblib.load(path)
    logger.debug(f"Loaded model pipeline from {path}")
    return pipeline


def predict_insurance_charge(
    input_profile: Dict[str, Any],
    pipeline: Optional[Pipeline] = None,
) -> Dict[str, Any]:
    """Validate user input and compute predicted charges using the trained pipeline.

    Args:
        input_profile: Dictionary with keys: age, sex, bmi, children, smoker, region.
        pipeline: Optional pre-loaded Scikit-Learn Pipeline. If None, loads best model.

    Returns:
        Dictionary containing prediction result, validated inputs, and disclaimer.

    Raises:
        ValueError: If inputs fail domain boundary validation.
    """
    # Step 1: Input validation
    is_valid, error_msg = validate_single_record(input_profile)
    if not is_valid:
        raise ValueError(f"Invalid input profile: {error_msg}")

    # Step 2: Ensure pipeline is available
    active_pipeline = pipeline if pipeline is not None else load_best_model()

    # Step 3: Format input into a single-row DataFrame matching training feature columns
    df_row = pd.DataFrame(
        [
            {
                "age": float(input_profile["age"]),
                "sex": str(input_profile["sex"]).strip().lower(),
                "bmi": float(input_profile["bmi"]),
                "children": int(input_profile["children"]),
                "smoker": str(input_profile["smoker"]).strip().lower(),
                "region": str(input_profile["region"]).strip().lower(),
            }
        ]
    )[ALL_FEATURES]

    # Step 4: Run inference
    raw_pred = float(active_pipeline.predict(df_row)[0])
    predicted_charge = max(0.0, raw_pred)  # Insurance charges cannot be negative

    return {
        "predicted_charge": round(predicted_charge, 2),
        "predicted_charge_formatted": f"${predicted_charge:,.2f}",
        "input_profile": df_row.iloc[0].to_dict(),
        "disclaimer": EDUCATIONAL_DISCLAIMER,
    }
